private readonly object _a = new object();
private readonly object _b = new object();

public void FirstThenSecond()
{
    lock (_a) { lock (_b) { DoWork(); } }
}

public void SecondThenFirst()
{
    lock (_b) { lock (_a) { DoWork(); } }
}

// If Thread 1 calls FirstThenSecond and Thread 2 calls SecondThenFirst
// simultaneously, both threads wait forever for the other to release a lock.
